/**
 * Personal project mutes: which projects a member has silenced.
 */
import { and, asc, eq, inArray, sql } from "drizzle-orm";
import { getDb, projectMutes } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { brandId } from "./_mappers";
import { orgPredicate } from "./base-repository";
import type { OrgId, ProjectId, UserId } from "@/types/common";

/** The projects `userId` has muted in this org, oldest mute first. */
export async function listMutedProjectIds(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ProjectId[]> {
  const rows = getDb()
    .select({ projectId: projectMutes.projectId })
    .from(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
      ),
    )
    .orderBy(asc(projectMutes.createdAt), sql`rowid`)
    .all();
  return rows.map((row) => brandId<ProjectId>(row.projectId));
}

/** Which of `userIds` have muted `projectId`; the fan-out asks once per event. */
export async function listMutedUserIds(
  orgId: OrgId,
  projectId: ProjectId,
  userIds: readonly UserId[],
): Promise<ReadonlySet<UserId>> {
  if (userIds.length === 0) return new Set();

  const rows = getDb()
    .select({ userId: projectMutes.userId })
    .from(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.projectId, projectId),
        inArray(projectMutes.userId, [...userIds]),
      ),
    )
    .all();
  return new Set(rows.map((row) => brandId<UserId>(row.userId)));
}

/** Idempotent: muting an already-muted project keeps the original mute. */
export async function addProjectMute(
  orgId: OrgId,
  projectId: ProjectId,
  userId: UserId,
): Promise<void> {
  getDb()
    .insert(projectMutes)
    .values({
      orgId,
      projectId,
      userId,
      createdAt: toIsoTimestamp(new Date()),
    })
    .onConflictDoNothing()
    .run();
}

/** Idempotent: unmuting a project that is not muted is a no-op. */
export async function removeProjectMute(
  orgId: OrgId,
  projectId: ProjectId,
  userId: UserId,
): Promise<void> {
  getDb()
    .delete(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.projectId, projectId),
        eq(projectMutes.userId, userId),
      ),
    )
    .run();
}
EOF
