/**
 * The digest leaves out notifications about projects the recipient has muted
 * at build time, keeps them unread, and caps what remains.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { DIGEST_MAX_ENTRIES } from "@/config/constants";
import { runDigestEmailJob } from "@/server/jobs/digest-email-job";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as emailService from "@/server/services/email-service";
import { muteProject, notify, unmuteProject } from "@/server/services/notification-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { ProjectId } from "@/types/common";

let cleanup: () => void;

const nowAtHour = (hour: number) => new Date(Date.UTC(2026, 5, 2, hour, 0, 0, 0));

async function makeTenant(slug: string, digestHourUtc: number): Promise<Tenant> {
  const tenant = await createTenant(slug, "growth");
  await orgRepo.updateOrg(tenant.org.id, {
    orgId: tenant.org.id,
    settings: { digestHourUtc },
  });
  await usageRepo.recomputeUsage(tenant.org.id);
  await preferenceRepo.upsertPreference({
    orgId: tenant.org.id,
    userId: tenant.userIds.member,
    kind: "comment_created",
    inApp: false,
    email: false,
    digestOnly: true,
  });
  return tenant;
}

async function insertAt(
  tenant: Tenant,
  at: Date,
  title: string,
  projectId: ProjectId | null,
): Promise<void> {
  vi.useFakeTimers();
  vi.setSystemTime(at);
  try {
    await notificationRepo.insertNotification(tenant.org.id, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      kind: "comment_created",
      title,
      body: title,
      href: "/issues/1",
      actorId: null,
      projectId,
      channels: ["email"],
    });
  } finally {
    vi.useRealTimers();
  }
}

function cell(html: string, key: string): string | null {
  return html.match(new RegExp(`<td>${key}</td><td>([^<]*)</td>`))?.[1] ?? null;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  vi.restoreAllMocks();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

describe("jobs/digest-email-job with muted projects", () => {
  it("leaves muted notifications out, unread, until they are unmuted", async () => {
    const now = nowAtHour(1);
    const tenant = await makeTenant("digest-mute", 1);
    const at = (hours: number) => new Date(now.getTime() - hours * 3_600_000);

    await insertAt(tenant, at(3), "Loud", null);
    // Created before the mute, still left out.
    await insertAt(tenant, at(2), "Quiet", tenant.project.id);
    await muteProject(tenant.actors.member, tenant.org.id, tenant.project.id);

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);
    await runDigestEmailJob(now);

    expect(sendSpy).toHaveBeenCalledTimes(1);
    const html = sendSpy.mock.calls[0]?.[0].html ?? "";
    expect(cell(html, "entryCount")).toBe("1");
    expect(cell(html, "headline")).toBe("Loud");

    // Still unread, so a later digest picks it up after the unmute.
    await unmuteProject(tenant.actors.member, tenant.org.id, tenant.project.id);
    await runDigestEmailJob(now);

    expect(sendSpy).toHaveBeenCalledTimes(2);
    const later = sendSpy.mock.calls[1]?.[0].html ?? "";
    expect(cell(later, "entryCount")).toBe("1");
    expect(cell(later, "headline")).toBe("Quiet");
  });

  it("sends nothing when only muted notifications remain", async () => {
    const now = nowAtHour(2);
    const tenant = await makeTenant("digest-mute-empty", 2);
    await notify(tenant.org.id, "comment_created", [tenant.userIds.member], {
      title: "About the project",
      body: "b",
      href: "/x",
      actorId: null,
      projectId: tenant.project.id,
    });
    await muteProject(tenant.actors.member, tenant.org.id, tenant.project.id);

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);
    const result = await runDigestEmailJob(new Date(Math.max(now.getTime(), Date.now())));
    void result;

    expect(sendSpy).not.toHaveBeenCalled();
  });

  it("applies the entry cap to what remains", async () => {
    const now = nowAtHour(3);
    const tenant = await makeTenant("digest-mute-cap", 3);
    await muteProject(tenant.actors.member, tenant.org.id, tenant.project.id);

    // The newest entries are muted; they must not use up the cap.
    for (let i = 0; i < DIGEST_MAX_ENTRIES; i += 1) {
      await insertAt(tenant, new Date(now.getTime() - (i + 1) * 1_000), `Muted ${i}`, tenant.project.id);
    }
    for (let i = 0; i < DIGEST_MAX_ENTRIES + 2; i += 1) {
      await insertAt(tenant, new Date(now.getTime() - (i + 100) * 1_000), `Open ${i}`, null);
    }

    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);
    await runDigestEmailJob(now);

    const html = sendSpy.mock.calls[0]?.[0].html ?? "";
    expect(cell(html, "entryCount")).toBe(String(DIGEST_MAX_ENTRIES));
    expect(cell(html, "headline")).toBe("Open 0");
  });
});
